import Foundation
import SafeDICore
import Testing
@testable import SafeDITool

struct SafeDIToolMockGenerationTests: ~Copyable {
	// MARK: Initialization

	init() throws {
		filesToDelete = [URL]()
	}

	deinit {
		for fileToDelete in filesToDelete {
			try! FileManager.default.removeItem(at: fileToDelete)
		}
	}

	// MARK: Tests – Simple types

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForTypeWithNoDependencies() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct SimpleType: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 1)
		#expect(output.mockFiles["SimpleType+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension SimpleType {
		    static func mock() -> SimpleType {
		        SimpleType()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["SimpleType+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForExtensionBasedInstantiable() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public class SomeThirdPartyType {}

				@Instantiable(generateMock: true)
				extension SomeThirdPartyType: Instantiable {
				    public static func instantiate() -> SomeThirdPartyType {
				        SomeThirdPartyType()
				    }
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 1)
		#expect(output.mockFiles["SomeThirdPartyType+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension SomeThirdPartyType {
		    static func mock() -> SomeThirdPartyType {
		        SomeThirdPartyType.instantiate()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["SomeThirdPartyType+SafeDIMock.swift"] ?? "")")
	}

	// MARK: Tests – Types with dependencies

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForTypeWithInstantiatedDependency() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(dependency: Dependency) {
				        self.dependency = dependency
				    }
				    @Instantiated let dependency: Dependency
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Dependency: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 2)
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            dependency: (() -> Dependency)? = nil
		        ) {
		            self.dependency = dependency
		        }

		        let dependency: (() -> Dependency)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let dependency = if let safeDIBuilder = safeDIOverrides.dependency { safeDIBuilder() } else { Dependency() }
		        return Root(dependency: dependency)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["Dependency+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Dependency {
		    static func mock() -> Dependency {
		        Dependency()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Dependency+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForTypeWithReceivedDependency() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(child: Child, shared: SharedThing) {
				        self.child = child
				        self.shared = shared
				    }
				    @Instantiated let child: Child
				    @Instantiated let shared: SharedThing
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Child: Instantiable {
				    public init(shared: SharedThing) {
				        self.shared = shared
				    }
				    @Received let shared: SharedThing
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct SharedThing: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 3)
		#expect(output.mockFiles["Child+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Child {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil
		        ) {
		            self.shared = shared
		        }

		        let shared: (() -> SharedThing)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Child {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        return Child(shared: shared)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Child+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil,
		            child: ((SharedThing) -> Child)? = nil
		        ) {
		            self.shared = shared
		            self.child = child
		        }

		        let shared: (() -> SharedThing)?
		        let child: ((SharedThing) -> Child)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        let child = if let safeDIBuilder = safeDIOverrides.child { safeDIBuilder(shared) } else { Child(shared: shared) }
		        return Root(child: child, shared: shared)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["SharedThing+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension SharedThing {
		    static func mock() -> SharedThing {
		        SharedThing()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["SharedThing+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForFullTree() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(childA: ChildA, shared: SharedThing) {
				        self.childA = childA
				        self.shared = shared
				    }
				    @Instantiated let childA: ChildA
				    @Instantiated let shared: SharedThing
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildA: Instantiable {
				    public init(shared: SharedThing, grandchild: Grandchild) {
				        self.shared = shared
				        self.grandchild = grandchild
				    }
				    @Received let shared: SharedThing
				    @Instantiated let grandchild: Grandchild
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Grandchild: Instantiable {
				    public init(shared: SharedThing) {
				        self.shared = shared
				    }
				    @Received let shared: SharedThing
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct SharedThing: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 4)
		#expect(output.mockFiles["ChildA+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension ChildA {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil,
		            grandchild: ((SharedThing) -> Grandchild)? = nil
		        ) {
		            self.shared = shared
		            self.grandchild = grandchild
		        }

		        let shared: (() -> SharedThing)?
		        let grandchild: ((SharedThing) -> Grandchild)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> ChildA {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        let grandchild = if let safeDIBuilder = safeDIOverrides.grandchild { safeDIBuilder(shared) } else { Grandchild(shared: shared) }
		        return ChildA(shared: shared, grandchild: grandchild)
		    }
		}
		#endif

		#if DEBUG
		extension ChildA {
		    /// Configuration for how this type is constructed within a mock tree.
		    struct SafeDIMockConfiguration {
		        init(
		            grandchild: ((SharedThing) -> Grandchild)? = nil,
		            _ safeDIBuilder: ((SharedThing, Grandchild) -> ChildA)? = nil
		        ) {
		            self.grandchild = grandchild
		            self.safeDIBuilder = safeDIBuilder
		        }

		        let grandchild: ((SharedThing) -> Grandchild)?
		        /// Overrides how this type is constructed. Parameters match the type’s initializer or custom mock method. When `nil`, the default generated construction function is used.
		        let safeDIBuilder: ((SharedThing, Grandchild) -> ChildA)?
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["ChildA+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["Grandchild+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Grandchild {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil
		        ) {
		            self.shared = shared
		        }

		        let shared: (() -> SharedThing)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Grandchild {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        return Grandchild(shared: shared)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Grandchild+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil,
		            childA: ChildA.SafeDIMockConfiguration = .init()
		        ) {
		            self.shared = shared
		            self.childA = childA
		        }

		        let shared: (() -> SharedThing)?
		        let childA: ChildA.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        func __safeDI_childA() -> ChildA {
		            let grandchild = if let safeDIBuilder = safeDIOverrides.childA.grandchild { safeDIBuilder(shared) } else { Grandchild(shared: shared) }
		            return if let safeDIBuilder = safeDIOverrides.childA.safeDIBuilder { safeDIBuilder(shared, grandchild) } else { ChildA(shared: shared, grandchild: grandchild) }
		        }
		        let childA: ChildA = __safeDI_childA()
		        return Root(childA: childA, shared: shared)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["SharedThing+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension SharedThing {
		    static func mock() -> SharedThing {
		        SharedThing()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["SharedThing+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_parameterRequiredForTypeNotInTypeMap() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol SomeProtocol {}

				@Instantiable(generateMock: true)
				public struct Consumer: Instantiable {
				    public init(dependency: SomeProtocol) {
				        self.dependency = dependency
				    }
				    @Received let dependency: SomeProtocol
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 1)
		#expect(output.mockFiles["Consumer+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Consumer {
		    static func mock(
		        dependency: SomeProtocol
		    ) -> Consumer {
		        return Consumer(dependency: dependency)
		    }
