		#endif
		""", "Unexpected output \(output.mockFiles["Consumer+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_receivedErasedTypeAutoWraps() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public class AnyService {
				    public init(_ service: some Any) {}
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(child: Child, myService: AnyService) {
				        self.child = child
				        self.myService = myService
				    }
				    @Instantiated let child: Child
				    @Instantiated(fulfilledByType: "ConcreteService", erasedToConcreteExistential: true) let myService: AnyService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Child: Instantiable {
				    public init(myService: AnyService) {
				        self.myService = myService
				    }
				    @Received let myService: AnyService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ConcreteService: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// Child receives AnyService, which is erased-to-concrete.
		// The mock should auto-detect this and provide AnyService parameter with inline wrapping.
		#expect(output.mockFiles.count == 3)
		#expect(output.mockFiles["Child+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Child {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            myService: (() -> AnyService)? = nil
		        ) {
		            self.myService = myService
		        }

		        let myService: (() -> AnyService)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Child {
		        let myService = if let safeDIBuilder = safeDIOverrides.myService { safeDIBuilder() } else { AnyService(ConcreteService()) }
		        return Child(myService: myService)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Child+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["ConcreteService+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension ConcreteService {
		    static func mock() -> ConcreteService {
		        ConcreteService()
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["ConcreteService+SafeDIMock.swift"] ?? "")")

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            myService: (() -> AnyService)? = nil,
		            child: ((AnyService) -> Child)? = nil
		        ) {
		            self.myService = myService
		            self.child = child
		        }

		        let myService: (() -> AnyService)?
		        let child: ((AnyService) -> Child)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let myService = if let safeDIBuilder = safeDIOverrides.myService { safeDIBuilder() } else { AnyService(ConcreteService()) }
		        let child = if let safeDIBuilder = safeDIOverrides.child { safeDIBuilder(myService) } else { Child(myService: myService) }
		        return Root(child: child, myService: myService)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_receivedErasedTypeIsRequiredParameter_whenDifferentConcreteTypesAreErasedToIt() async throws {
		// Before the fix, the mock built whichever erasure a dictionary iteration
		// visited last, so it changed from run to run. No run produced a required
		// parameter, so this expectation failed on every run, not just some.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol Service {}

				public struct AnyService {
				    public init(_ service: some Service) {}
				}
				""",
				"""
				@Instantiable
				public final class ServiceA: Service, Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable
				public final class ServiceB: Service, Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable
				public final class HostA: Instantiable {
				    public init(service: AnyService, user: User) {
				        self.service = service
				        self.user = user
				    }
				    @Instantiated(fulfilledByType: "ServiceA", erasedToConcreteExistential: true) let service: AnyService
				    @Instantiated let user: User
				}
				""",
				"""
				@Instantiable
				public final class HostB: Instantiable {
				    public init(service: AnyService, user: User) {
				        self.service = service
				        self.user = user
				    }
				    @Instantiated(fulfilledByType: "ServiceB", erasedToConcreteExistential: true) let service: AnyService
				    @Instantiated let user: User
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class User: Instantiable {
				    public init(service: AnyService) {
				        self.service = service
				    }
				    @Received let service: AnyService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 1)
		#expect(output.mockFiles["User+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension User {
		    static func mock(
		        service: AnyService
		    ) -> User {
		        return User(service: service)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["User+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_receivedErasedTypeIsRequiredParameterThreadedToChild_whenDifferentConcreteTypesAreErasedToIt() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol Service {}

				public struct AnyService {
				    public init(_ service: some Service) {}
				}
				""",
				"""
				@Instantiable
				public final class ServiceA: Service, Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable
				public final class ServiceB: Service, Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable
				public final class HostA: Instantiable {
				    public init(service: AnyService) {
				        self.service = service
				    }
				    @Instantiated(fulfilledByType: "ServiceA", erasedToConcreteExistential: true) let service: AnyService
				}
				""",
				"""
				@Instantiable
				public final class HostB: Instantiable {
				    public init(service: AnyService) {
				        self.service = service
				    }
				    @Instantiated(fulfilledByType: "ServiceB", erasedToConcreteExistential: true) let service: AnyService
