	@Test(arguments: MultiModuleIntegration.allCases)
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_receivedErasedTypeIsRequiredParameter_whenDependentModuleErasesADifferentConcreteTypeToIt(integration: MultiModuleIntegration) async throws {
		let output = try await executeSafeDIToolMultiModuleTest(
			modules: [
				ModuleFixture(
					name: "Services",
					packageName: "App",
					swiftFileContent: [
						"""
						public protocol Service {}

						public struct AnyService {
						    public init(_ service: some Service) {}
						}
						""",
						"""
						@Instantiable
						public final class ServiceA: Service, Instantiable {
						    public init() {}
						}
						""",
						"""
						@Instantiable
						public final class HostA: Instantiable {
						    public init(service: AnyService) {
						        self.service = service
						    }
						    @Instantiated(fulfilledByType: "ServiceA", erasedToConcreteExistential: true) let service: AnyService
						}
						""",
					],
				),
				ModuleFixture(
					name: "Users",
					packageName: "App",
					swiftFileContent: [
						"""
						import Services

						@Instantiable
						public final class ServiceB: Service, Instantiable {
						    public init() {}
						}
						""",
						"""
						import Services

						@Instantiable
						public final class HostB: Instantiable {
						    public init(service: AnyService) {
						        self.service = service
						    }
						    @Instantiated(fulfilledByType: "ServiceB", erasedToConcreteExistential: true) let service: AnyService
						}
						""",
						"""
						import Services

						@Instantiable(generateMock: true)
						public final class User: Instantiable {
						    public init(service: AnyService) {
						        self.service = service
						    }
						    @Received let service: AnyService
						}
						""",
					],
					dependencies: ["Services"],
				),
			],
			integration: integration,
			filesToDelete: &filesToDelete,
		)

		let header = generatedFileHeader
		let importBlock = """
		#if canImport(Services)
		import Services
		#endif

		"""
		let mockCode = """
		#if DEBUG
		extension User {
		    static func mock(
		        service: AnyService
		    ) -> User {
		        return User(service: service)
		    }
		}
		#endif
		"""
		let expectedGeneratedFiles: [String: [String: String]] = switch integration {
		case .moduleInfo:
			[
				"Services": ["Services.swift": header],
				"Users": ["Users.swift": header + importBlock + "\n" + mockCode],
			]
		case .swiftPackagePlugin:
			[
				"Services": [:],
				"Users": [
					"SafeDIMockConfiguration.swift": header + importBlock + "\n",
					"User+SafeDIMock.swift": header + importBlock + "\n" + mockCode,
				],
			]
		}
		#expect(output.modules.mapValues(\.generatedFiles) == expectedGeneratedFiles)
	}

