	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_erasedToConcreteExistentialWithMockInitializer() async throws {
		// The concrete type has a hand-written mock with a parameter. The erased
		// default path should call the mock method (not init) and wrap the result.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol MyService {}

				public final class AnyMyService: MyService {
				    public init(_ myService: some MyService) {}
				}
				""",
				"""
				@Instantiable(fulfillingAdditionalTypes: [MyService.self])
				public struct DefaultMyService: Instantiable, MyService {
				    public init(tag: String = "default") {
				        self.tag = tag
				    }
				    let tag: String
				    public static func mock(tag: String = "test") -> DefaultMyService { DefaultMyService(tag: tag) }
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public final class Root: Instantiable {
				    public init(myService: AnyMyService) {
				        self.myService = myService
				    }
				    @Instantiated(fulfilledByType: "DefaultMyService", erasedToConcreteExistential: true) let myService: AnyMyService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            myService: DefaultMyService.SafeDIMockConfiguration = .init()
		        ) {
		            self.myService = myService
		        }

		        let myService: DefaultMyService.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_myService() -> AnyMyService {
		            return if let safeDIBuilder = safeDIOverrides.myService.safeDIBuilder { AnyMyService(safeDIBuilder(safeDIOverrides.myService.tag)) } else { AnyMyService(DefaultMyService.mock(tag: safeDIOverrides.myService.tag)) }
		        }
		        let myService: AnyMyService = __safeDI_myService()
		        return Root(myService: myService)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_erasedExistentialWithAliasedDependency_doesNotDoubleWrapOverride() async throws {
		// Regression: when a constant erased-existential node has aliased
		// dependencies but no children/defaults/cycles, it enters the
		// function-wrapper branch via `requiresFunctionWrapper` while
		// `needsConfigurationStruct == false`. The override closure stored at
		// `safeDIOverrides.<label>` already returns the property (wrapper) type
		// — wrapping it a second time produces invalid Swift.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol MyService {}

				public final class AnyMyService: MyService {
				    public init(_ myService: some MyService) {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Provider: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(fulfillingAdditionalTypes: [MyService.self], generateMock: true)
				public struct DefaultMyService: Instantiable, MyService {
				    public init(provider: Provider) {
				        self.provider = provider
				    }
				    @Received(fulfilledByDependencyNamed: "providerService", ofType: Provider.self) let provider: Provider
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public final class Root: Instantiable {
				    public init(providerService: Provider, myService: AnyMyService) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }
				    @Instantiated let providerService: Provider
				    @Instantiated(fulfilledByType: "DefaultMyService", erasedToConcreteExistential: true) let myService: AnyMyService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            providerService: (() -> Provider)? = nil,
		            myService: ((Provider) -> AnyMyService)? = nil
		        ) {
		            self.providerService = providerService
		            self.myService = myService
		        }

		        let providerService: (() -> Provider)?
		        let myService: ((Provider) -> AnyMyService)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let providerService = if let safeDIBuilder = safeDIOverrides.providerService { safeDIBuilder() } else { Provider() }
		        func __safeDI_myService() -> AnyMyService {
		            #sourceLocation(file: "\(output.fixtures["DefaultMyService.swift"])", line: 6)
		            let provider: Provider = providerService
		            #sourceLocation()
		            return if let safeDIBuilder = safeDIOverrides.myService { safeDIBuilder(provider) } else { AnyMyService(DefaultMyService(provider: provider)) }
		        }
		        let myService: AnyMyService = __safeDI_myService()
		        return Root(providerService: providerService, myService: myService)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

