		    ) -> Parent {
		        func __safeDI_sBuilder(x: X) -> S {
		            let user = if let safeDIBuilder = safeDIOverrides.sBuilder.user { safeDIBuilder(x) } else { User(x: x) }
		            return if let safeDIBuilder = safeDIOverrides.sBuilder.safeDIBuilder { safeDIBuilder(x, user) } else { S(x: x, user: user) }
