	mutating func mock_remapsAliasToPathJoinedToProjectRoot_whenGenerateReusesParseThatScanCached() async throws {
		// On macOS the fixture directory's real path begins with `/private`, which the compiler keeps and
		// Foundation's path standardization removes.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public struct User: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Child: Instantiable {
				    public init(renamedUser: User) {
				        self.renamedUser = renamedUser
				    }
				    @Received(fulfilledByDependencyNamed: "user", ofType: User.self) let renamedUser: User
				}
				""",
			],
			pluginInvocation: .scanWhilePlanning(reportsFixtureDirectoryThroughSymbolicLink: false),
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Child+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

