		        init(
		            user: (() -> User)? = nil
		        ) {
		            self.user = user
		        }

		        let user: (() -> User)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Child {
		        let user = if let safeDIBuilder = safeDIOverrides.user { safeDIBuilder() } else { User() }
		        #sourceLocation(file: "\(output.fixtures.compilerPath(of: "Child.swift"))", line: 6)
		        let renamedUser: User = user
		        #sourceLocation()
		        return Child(renamedUser: renamedUser)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Child+SafeDIMock.swift"] ?? "")")
	}

