	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_readsOnlyReachableOverridesBeforeSendableFunction_whenInstantiatorCycleIsNestedInSendableInstantiator() async throws {
		// X → B → A → B, with the (B, A) back-edge pruned from B's
		// configuration. Inside the sendable `xBuilder` function, A and its
		// `helper` have no reachable override slot, so only B's overrides are
		// read before the function.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Helper: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class Other: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(xBuilder: SendableInstantiator<X>, other: Other) {
				        self.xBuilder = xBuilder
				        self.other = other
				    }
				    @Instantiated let xBuilder: SendableInstantiator<X>
				    @Instantiated let other: Other
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct X: Instantiable {
				    public init(bBuilder: Instantiator<B>) {
				        self.bBuilder = bBuilder
				    }
				    @Instantiated let bBuilder: Instantiator<B>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct A: Instantiable {
				    public init(bBuilder: Instantiator<B>, helper: Helper, label: String = "default") {
				        self.bBuilder = bBuilder
				        self.helper = helper
				        self.label = label
				    }
				    @Instantiated let bBuilder: Instantiator<B>
				    @Instantiated let helper: Helper
				    let label: String
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct B: Instantiable {
				    public init(aBuilder: Instantiator<A>, helper: Helper) {
				        self.aBuilder = aBuilder
				        self.helper = helper
				    }
				    @Instantiated let aBuilder: Instantiator<A>
				    @Instantiated let helper: Helper
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            xBuilder: X.SafeDIMockConfiguration = .init(),
		            other: (() -> Other)? = nil
		        ) {
		            self.xBuilder = xBuilder
		            self.other = other
		        }

		        let xBuilder: X.SafeDIMockConfiguration
		        let other: (() -> Other)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let __safeDI_xBuilder__xBuilder_bBuilder_safeDIBuilder = safeDIOverrides.xBuilder.bBuilder.safeDIBuilder
		        let __safeDI_xBuilder__xBuilder_bBuilder_helper_safeDIBuilder = safeDIOverrides.xBuilder.bBuilder.helper
		        let __safeDI_xBuilder__safeDIBuilder = safeDIOverrides.xBuilder.safeDIBuilder
		        @Sendable func __safeDI_xBuilder() -> X {
		            func __safeDI_bBuilder() -> B {
		                func __safeDI_aBuilder() -> A {
		                    let bBuilder = Instantiator<B>(__safeDI_bBuilder)
		                    let helper = Helper()
		                    return A(bBuilder: bBuilder, helper: helper)
		                }
		                let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		                let helper = if let safeDIBuilder = __safeDI_xBuilder__xBuilder_bBuilder_helper_safeDIBuilder { safeDIBuilder() } else { Helper() }
		                return if let safeDIBuilder = __safeDI_xBuilder__xBuilder_bBuilder_safeDIBuilder { safeDIBuilder(aBuilder, helper) } else { B(aBuilder: aBuilder, helper: helper) }
		            }
		            let bBuilder = Instantiator<B>(__safeDI_bBuilder)
		            return if let safeDIBuilder = __safeDI_xBuilder__safeDIBuilder { safeDIBuilder(bBuilder) } else { X(bBuilder: bBuilder) }
		        }
		        let xBuilder = SendableInstantiator<X>(__safeDI_xBuilder)
		        let other = if let safeDIBuilder = safeDIOverrides.other { safeDIBuilder() } else { Other() }
		        return Root(xBuilder: xBuilder, other: other)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

