	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_aliasedReceivedFulfilledByLocalInstantiatedSibling_sharesSingleInstanceAndEmitsNoRootPromotion() async throws {
		// Regression test for the alias-on-instantiated-sibling case. Consumer
		// declares an @Instantiated `service: Service` AND an @Received alias
		// `alias: Service` fulfilled by the same local `service`. The mock must:
		//   (1) NOT promote `service` to a root-level flat parameter (the alias
		//       is locally satisfied by Consumer's own @Instantiated).
		//   (2) Emit Consumer's `let service = ...` BEFORE `let alias: Service = service`
		//       so the alias resolves to the same instance as production.
		// Before the fix, the alias was emitted ahead of the local binding,
		// producing either a Swift forward-reference error or a second Service
		// instance supplied by a promoted root flat param.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(consumer: Consumer) {
				        self.consumer = consumer
				    }
				    @Instantiated let consumer: Consumer
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Consumer: Instantiable {
				    public init(service: Service, alias: Service) {
				        self.service = service
				        self.alias = alias
				    }
				    @Instantiated let service: Service
				    @Received(fulfilledByDependencyNamed: "service", ofType: Service.self, erasedToConcreteExistential: false) let alias: Service
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Service: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            consumer: Consumer.SafeDIMockConfiguration = .init()
		        ) {
		            self.consumer = consumer
		        }

		        let consumer: Consumer.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_consumer() -> Consumer {
		            let service = if let safeDIBuilder = safeDIOverrides.consumer.service { safeDIBuilder() } else { Service() }
		            #sourceLocation(file: "\(output.fixtures["Consumer.swift"])", line: 8)
		            let alias: Service = service
		            #sourceLocation()
		            return if let safeDIBuilder = safeDIOverrides.consumer.safeDIBuilder { safeDIBuilder(service, alias) } else { Consumer(service: service, alias: alias) }
		        }
		        let consumer: Consumer = __safeDI_consumer()
		        return Root(consumer: consumer)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		// Consumer's standalone mock likewise binds the alias to the local.
		#expect(output.mockFiles["Consumer+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Consumer {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            service: (() -> Service)? = nil
		        ) {
		            self.service = service
		        }

		        let service: (() -> Service)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Consumer {
		        let service = if let safeDIBuilder = safeDIOverrides.service { safeDIBuilder() } else { Service() }
		        #sourceLocation(file: "\(output.fixtures["Consumer.swift"])", line: 8)
		        let alias: Service = service
		        #sourceLocation()
		        return Consumer(service: service, alias: alias)
		    }
		}
		#endif

		#if DEBUG
		extension Consumer {
		    /// Configuration for how this type is constructed within a mock tree.
		    struct SafeDIMockConfiguration {
		        init(
		            service: (() -> Service)? = nil,
		            _ safeDIBuilder: ((Service, Service) -> Consumer)? = nil
		        ) {
		            self.service = service
		            self.safeDIBuilder = safeDIBuilder
		        }

		        let service: (() -> Service)?
		        /// Overrides how this type is constructed. Parameters match the type’s initializer or custom mock method. When `nil`, the default generated construction function is used.
		        let safeDIBuilder: ((Service, Service) -> Consumer)?
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Consumer+SafeDIMock.swift"] ?? "")")
	}

