	@Test(arguments: MultiModuleIntegration.allCases)
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_instantiatedDependencyFromAnotherModuleGetsDefault_whenRunUnderEitherIntegration(integration: MultiModuleIntegration) async throws {
		let output = try await executeSafeDIToolMultiModuleTest(
			modules: [
				// First module: ExternalEngine is @Instantiable via extension in another module.
				ModuleFixture(
					name: "Engines",
					packageName: "App",
					swiftFileContent: [
						"""
						public struct ExternalEngine: Sendable {
						    public init(handler: @escaping @Sendable () -> Void) {
						        self.handler = handler
						    }
						    private let handler: @Sendable () -> Void
						}
						""",
						"""
						@Instantiable
						extension ExternalEngine: Instantiable {
						    public static func instantiate() -> ExternalEngine {
						        .init(handler: {})
						    }
						}
						""",
					],
				),
				// Second module: Service @Instantiated ExternalEngine. The dependency's declarations – its
				// `.safedi`, or its files in the CSV – make ExternalEngine constructible, and the generated
				// mock imports the module, so ExternalEngine.instantiate() is available.
				ModuleFixture(
					name: "Services",
					packageName: "App",
					swiftFileContent: [
						"""
						import Engines

						@Instantiable(generateMock: true)
						public struct Service: Instantiable {
						    public init(externalEngine: ExternalEngine, name: String) {
						        self.externalEngine = externalEngine
						        self.name = name
						    }
						    @Instantiated let externalEngine: ExternalEngine
						    @Received let name: String
						}
						""",
					],
					dependencies: ["Engines"],
				),
			],
			integration: integration,
			filesToDelete: &filesToDelete,
		)

		let header = generatedFileHeader
		let importBlock = """
		#if canImport(Engines)
		import Engines
		#endif

		"""
		// ExternalEngine is constructible from the dependency's declarations — the generated mock
		// imports the module, so ExternalEngine.instantiate() is available. The parameter
		// is optional with a default construction.
		let mockCode = """
		#if DEBUG
		extension Service {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            externalEngine: (() -> ExternalEngine)? = nil
		        ) {
		            self.externalEngine = externalEngine
		        }

		        let externalEngine: (() -> ExternalEngine)?
		    }

		    static func mock(
		        name: String,
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Service {
		        let externalEngine = if let safeDIBuilder = safeDIOverrides.externalEngine { safeDIBuilder() } else { ExternalEngine.instantiate() }
		        return Service(externalEngine: externalEngine, name: name)
		    }
		}
		#endif
		"""
		let expectedGeneratedFiles: [String: [String: String]] = switch integration {
		case .moduleInfo:
			[
				"Engines": ["Engines.swift": header],
				"Services": ["Services.swift": header + importBlock + "\n" + mockCode],
			]
		case .swiftPackagePlugin:
			[
				"Engines": [:],
				"Services": [
					"SafeDIMockConfiguration.swift": header + importBlock + "\n",
					"Service+SafeDIMock.swift": header + importBlock + "\n" + mockCode,
				],
			]
		}
		#expect(output.modules.mapValues(\.generatedFiles) == expectedGeneratedFiles)
	}

