				"""
				@Instantiable(generateMock: true)
				public struct SharedThing: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildA: Instantiable {
				    public init(shared: SharedThing) {
				        self.shared = shared
				    }
				    @Received let shared: SharedThing
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildB: Instantiable {
				    public init(shared: SharedThing) {
				        self.shared = shared
				    }
				    @Instantiated let shared: SharedThing
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// Parent does NOT directly @Instantiate SharedThing.
		// ChildB @Instantiates it, ChildA @Receives it.
		// The mock promotes SharedThing at root scope so it's visible
		// to all children. Each child's nested function allows path-specific overrides.
		#expect(output.mockFiles["Parent+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Parent {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            shared: (() -> SharedThing)? = nil,
		            childA: ((SharedThing) -> ChildA)? = nil,
		            childB: ChildB.SafeDIMockConfiguration = .init()
		        ) {
		            self.shared = shared
		            self.childA = childA
		            self.childB = childB
		        }

		        let shared: (() -> SharedThing)?
		        let childA: ((SharedThing) -> ChildA)?
		        let childB: ChildB.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Parent {
		        let shared = if let safeDIBuilder = safeDIOverrides.shared { safeDIBuilder() } else { SharedThing() }
		        let childA = if let safeDIBuilder = safeDIOverrides.childA { safeDIBuilder(shared) } else { ChildA(shared: shared) }
		        func __safeDI_childB() -> ChildB {
		            let shared = if let safeDIBuilder = safeDIOverrides.childB.shared { safeDIBuilder() } else { SharedThing() }
		            return if let safeDIBuilder = safeDIOverrides.childB.safeDIBuilder { safeDIBuilder(shared) } else { ChildB(shared: shared) }
		        }
