	mutating func mock_noUseBeforeDeclarationWhenReceivedDependencyPromotedFromDeepTree() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct StateService: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ImageLoader: Instantiable {
				    public init(stateService: StateService) {
				        self.stateService = stateService
				    }
				    @Received let stateService: StateService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Engine: Instantiable {
				    public init(stateService: StateService) {
				        self.stateService = stateService
				    }
				    @Instantiated let stateService: StateService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Container: Instantiable {
				    public init(imageLoader: ImageLoader, engine: Engine) {
				        self.imageLoader = imageLoader
				        self.engine = engine
				    }
				    @Instantiated let imageLoader: ImageLoader
				    @Instantiated let engine: Engine
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// stateService is @Received by ImageLoader and @Instantiated by Engine.
		// In Container's mock:
		// - stateService is promoted at root scope (for ImageLoader)
		// - Engine's nested function has its own local stateService (valid shadowing)
		// - stateService must be declared BEFORE imageLoader references it
		#expect(output.mockFiles["Container+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Container {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            stateService: (() -> StateService)? = nil,
		            imageLoader: ((StateService) -> ImageLoader)? = nil,
		            engine: Engine.SafeDIMockConfiguration = .init()
		        ) {
		            self.stateService = stateService
		            self.imageLoader = imageLoader
		            self.engine = engine
		        }

		        let stateService: (() -> StateService)?
		        let imageLoader: ((StateService) -> ImageLoader)?
		        let engine: Engine.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Container {
		        let stateService = if let safeDIBuilder = safeDIOverrides.stateService { safeDIBuilder() } else { StateService() }
		        let imageLoader = if let safeDIBuilder = safeDIOverrides.imageLoader { safeDIBuilder(stateService) } else { ImageLoader(stateService: stateService) }
		        func __safeDI_engine() -> Engine {
		            let stateService = if let safeDIBuilder = safeDIOverrides.engine.stateService { safeDIBuilder() } else { StateService() }
		            return if let safeDIBuilder = safeDIOverrides.engine.safeDIBuilder { safeDIBuilder(stateService) } else { Engine(stateService: stateService) }
		        }
		        let engine: Engine = __safeDI_engine()
		        return Container(imageLoader: imageLoader, engine: engine)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Container+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_noRedeclarationWhenSameDependencyIsReceivedAndOnlyIfAvailable() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Config: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildA: Instantiable {
				    public init(config: Config) {
				        self.config = config
				    }
				    @Received let config: Config
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildB: Instantiable {
				    public init(config: Config?) {
				        self.config = config
				    }
				    @Received(onlyIfAvailable: true) let config: Config?
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Parent: Instantiable {
				    public init(childA: ChildA, childB: ChildB) {
				        self.childA = childA
				        self.childB = childB
				    }
				    @Instantiated let childA: ChildA
				    @Instantiated let childB: ChildB
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// ChildA @Received config (required), ChildB @Received(onlyIfAvailable: true) config.
		// Parent's mock must declare config exactly once at root scope, not twice.
		let parentMock = try #require(output.mockFiles["Parent+SafeDIMock.swift"])
		// Count root-level "let config" bindings (before any func __safeDI)
		let bodyStart = try #require(parentMock.range(of: ") -> Parent {")?.upperBound)
		let bodyEnd = try #require(parentMock.range(of: "return Parent(")?.lowerBound)
		let body = String(parentMock[bodyStart..<bodyEnd])
		// Filter to only root-level bindings (not indented inside functions)
		let rootBindings = body.split(separator: "\n").filter {
			$0.trimmingCharacters(in: .whitespaces).hasPrefix("let config")
				&& !$0.contains("            ") // not deeply indented (inside function)
		}
		#expect(rootBindings.count == 1, "config should be declared exactly once at root scope, found \(rootBindings.count). Output: \(parentMock)")
	}

