	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_aliasedOnlyIfAvailableDependencyTracksOnlyIfAvailable() async throws {
		// An aliased dependency with onlyIfAvailable: true should produce an optional
		// mock parameter, not a required one. This exercises the aliased+onlyIfAvailable
		// path in collectReceivedProperties.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol ServiceProtocol {}

				@Instantiable(fulfillingAdditionalTypes: [ServiceProtocol.self], generateMock: true)
				public struct ConcreteService: ServiceProtocol, Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Consumer: Instantiable {
				    public init(service: ServiceProtocol?) {
				        self.service = service
				    }
				    @Received(fulfilledByDependencyNamed: "concreteService", ofType: ConcreteService.self, onlyIfAvailable: true) let service: ServiceProtocol?
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Parent: Instantiable {
				    public init(consumer: Consumer) {
				        self.consumer = consumer
				    }
				    @Instantiated let consumer: Consumer
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// Consumer has an aliased onlyIfAvailable dependency on ConcreteService (via ServiceProtocol).
		// The mock for Parent should make concreteService optional (not required) — no default
		// construction. Consumer's alias is emitted as a `let service: ServiceProtocol? = concreteService`
		// binding inside a `__safeDI_consumer()` wrapper.
		#expect(output.mockFiles["Parent+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Parent {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            consumer: ((ServiceProtocol?) -> Consumer)? = nil,
		            concreteService: ConcreteService? = nil
		        ) {
		            self.consumer = consumer
		            self.concreteService = concreteService
		        }

		        let consumer: ((ServiceProtocol?) -> Consumer)?
		        let concreteService: ConcreteService?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Parent {
		        let concreteService: ConcreteService? = safeDIOverrides.concreteService
		        func __safeDI_consumer() -> Consumer {
		            #sourceLocation(file: "\(output.fixtures["Consumer.swift"])", line: 6)
		            let service: ServiceProtocol? = concreteService
		            #sourceLocation()
		            return if let safeDIBuilder = safeDIOverrides.consumer { safeDIBuilder(service) } else { Consumer(service: service) }
		        }
		        let consumer: Consumer = __safeDI_consumer()
		        return Parent(consumer: consumer)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Parent+SafeDIMock.swift"] ?? "")")
	}

