	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_onlyIfAvailableTransitiveDependenciesNotPromoted() async throws {
		// When an onlyIfAvailable dependency (e.g., ApplicationStateService?) has its own
		// transitive dependencies (e.g., NotificationCenter), those transitive deps should
		// NOT be promoted at the root scope. The onlyIfAvailable dep isn't constructed at
		// root level — it's just an optional override parameter — so its transitive needs
		// are irrelevant.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct NotificationCenter: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ApplicationStateService: Instantiable {
				    public init(notificationCenter: NotificationCenter) {
				        self.notificationCenter = notificationCenter
				    }
				    @Received let notificationCenter: NotificationCenter
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ImageService: Instantiable {
				    public init(applicationStateService: ApplicationStateService?) {
				        self.applicationStateService = applicationStateService
				    }
				    @Received(onlyIfAvailable: true) let applicationStateService: ApplicationStateService?
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ProfileService: Instantiable {
				    public init(imageService: ImageService) {
				        self.imageService = imageService
				    }
				    @Instantiated let imageService: ImageService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// ProfileService → ImageService → @Received(onlyIfAvailable) ApplicationStateService?
		// ApplicationStateService needs NotificationCenter, but since ApplicationStateService
		// is onlyIfAvailable, NotificationCenter should NOT appear in the mock.
		#expect(output.mockFiles["ProfileService+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension ProfileService {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            imageService: ((ApplicationStateService?) -> ImageService)? = nil,
		            applicationStateService: ApplicationStateService? = nil
		        ) {
		            self.imageService = imageService
		            self.applicationStateService = applicationStateService
		        }

		        let imageService: ((ApplicationStateService?) -> ImageService)?
		        let applicationStateService: ApplicationStateService?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> ProfileService {
		        let applicationStateService: ApplicationStateService? = safeDIOverrides.applicationStateService
		        let imageService = if let safeDIBuilder = safeDIOverrides.imageService { safeDIBuilder(applicationStateService) } else { ImageService(applicationStateService: applicationStateService) }
		        return ProfileService(imageService: imageService)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["ProfileService+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_passesNilToOnlyIfAvailableReceiver_whenPromotedDependencyIsBuiltFromReceiversAncestor() async throws {
		// Child.mock() promotes `c` (Child receives it) and `b` (C receives it).
		// Worker, built inside `b`, receives `c` only if available — but `c` is
		// built from `b`, so handing Worker the promoted `c` would need `c` before
		// `b` and `b` before `c`. Production builds `b` where no `C` exists and
		// passes `nil`; the mock must do the same and build `b` first.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public final class Root: Instantiable {
				    public init(b: B, scope: Scope) { self.b = b; self.scope = scope }
				    @Instantiated let b: B
				    @Instantiated let scope: Scope
				}
				""",
				"""
				@Instantiable
				public final class B: Instantiable {
				    public init(worker: Worker) { self.worker = worker }
				    @Instantiated let worker: Worker
				}
				""",
				"""
				@Instantiable
				public final class Worker: Instantiable {
				    public init(c: C?) { self.c = c }
				    @Received(onlyIfAvailable: true) let c: C?
				}
				""",
				"""
				@Instantiable
				public final class Scope: Instantiable {
				    public init(c: C, child: Child) { self.c = c; self.child = child }
				    @Instantiated let c: C
				    @Instantiated let child: Child
				}
				""",
				"""
				@Instantiable
				public final class C: Instantiable {
				    public init(b: B) { self.b = b }
				    @Received let b: B
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class Child: Instantiable {
				    public init(c: C) { self.c = c }
				    @Received let c: C
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Child+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Child {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            b: B.SafeDIMockConfiguration = .init(),
		            c: ((B) -> C)? = nil
		        ) {
		            self.b = b
		            self.c = c
		        }

		        let b: B.SafeDIMockConfiguration
		        let c: ((B) -> C)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Child {
		        func __safeDI_b() -> B {
		            let worker = if let safeDIBuilder = safeDIOverrides.b.worker { safeDIBuilder(nil) } else { Worker(c: nil) }
		            return if let safeDIBuilder = safeDIOverrides.b.safeDIBuilder { safeDIBuilder(worker) } else { B(worker: worker) }
		        }
		        let b: B = __safeDI_b()
		        let c = if let safeDIBuilder = safeDIOverrides.c { safeDIBuilder(b) } else { C(b: b) }
		        return Child(c: c)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Child+SafeDIMock.swift"] ?? "")")
	}

