		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let a = if let safeDIBuilder = safeDIOverrides.a { safeDIBuilder(nil) } else { A(b: nil) }
		        func __safeDI_b() -> B {
		            let x = if let safeDIBuilder = safeDIOverrides.b.x { safeDIBuilder(a) } else { X(a: a) }
		            let y = if let safeDIBuilder = safeDIOverrides.b.y { safeDIBuilder(a) } else { Y(a: a) }
