		// N receives `x: X?` only if available, and `x` requires `p`, inside whose tree N is built, so N gets `nil`.
		// `p`'s tree also declares C's `onlyIfAvailable` alias `y` of `x: X?`, which D requires, beneath M, which
		// forwards `x: X`: the alias is created from M's `x`, so it needs nothing of Parent's `x`.
