				public final class Parent: Instantiable {
				    public init(p: P, x: X) { self.p = p; self.x = x }
				    @Instantiated let p: P
				    @Instantiated let x: X
				}
				""",
				"""
				@Instantiable
				public final class X: Instantiable {
				    public init(p: P) { self.p = p }
				    @Received let p: P
				}
				""",
				"""
				@Instantiable
				public final class P: Instantiable {
				    public init(mBuilder: Instantiator<M>, n: N) { self.mBuilder = mBuilder; self.n = n }
				    @Instantiated let mBuilder: Instantiator<M>
				    @Instantiated let n: N
				}
				""",
				"""
				@Instantiable
				public final class N: Instantiable {
				    public init(x: X?) { self.x = x }
				    @Received(onlyIfAvailable: true) let x: X?
				}
				""",
				"""
				@Instantiable
				public final class M: Instantiable {
				    public init(x: X, c: C) { self.x = x; self.c = c }
				    @Forwarded let x: X
				    @Instantiated let c: C
				}
				""",
				"""
				@Instantiable
				public final class C: Instantiable {
				    public init(y: X?, d: D) { self.y = y; self.d = d }
				    @Received(fulfilledByDependencyNamed: "x", ofType: X?.self, onlyIfAvailable: true) let y: X?
				    @Instantiated let d: D
				}
				""",
				"""
				@Instantiable
				public final class D: Instantiable {
				    public init(y: X?) { self.y = y }
				    @Received let y: X?
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
