		// ChildA @Instantiates `service: LocalService` (tree child).
		// ChildB @Receives `service: ExternalService` (different type, same label).
		// The received ExternalService must still be promoted — LocalService must not suppress it.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(childA: ChildA, childB: ChildB) {
				        self.childA = childA
				        self.childB = childB
				    }
				    @Instantiated let childA: ChildA
				    @Instantiated let childB: ChildB
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildA: Instantiable {
				    public init(service: LocalService) {
				        self.service = service
				    }
				    @Instantiated let service: LocalService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildB: Instantiable {
				    public init(service: ExternalService) {
				        self.service = service
				    }
				    @Received let service: ExternalService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct LocalService: Instantiable {
				    public init() {}
				}
				""",
				"""
				public struct ExternalService {}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// ExternalService has no @Instantiable — it must be a required autoclosure parameter.
		// LocalService IS @Instantiable — it's a leaf with default construction.
		// Both appear with label "service" but different types → both must exist.
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            childA: ChildA.SafeDIMockConfiguration = .init(),
		            childB: ((ExternalService) -> ChildB)? = nil
		        ) {
		            self.childA = childA
		            self.childB = childB
		        }

		        let childA: ChildA.SafeDIMockConfiguration
		        let childB: ((ExternalService) -> ChildB)?
		    }

		    static func mock(
		        service: ExternalService,
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_childA() -> ChildA {
		            let service = if let safeDIBuilder = safeDIOverrides.childA.service { safeDIBuilder() } else { LocalService() }
		            return if let safeDIBuilder = safeDIOverrides.childA.safeDIBuilder { safeDIBuilder(service) } else { ChildA(service: service) }
		        }
		        let childA: ChildA = __safeDI_childA()
		        let childB = if let safeDIBuilder = safeDIOverrides.childB { safeDIBuilder(service) } else { ChildB(service: service) }
		        return Root(childA: childA, childB: childB)
		    }
		}
		#endif
		""", "Unexpected Root output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

