	mutating func mock_uncoveredTransitiveDependencyFromParallelModuleSurfacesAsRequired() async throws {
		// Simulates a dependency whose transitive dep is @Instantiable in a parallel
		// module not available to this module. The transitive dep has no scope in the
		// mock map and must surface as a required parameter.
		//
		// Setup: "Services" module has DependentService with @Instantiated parallelModuleType.
		// parallelModuleType is NOT @Instantiable in any .safedi available to this module.
		// Root module has Root → DependentService (via .safedi from Services).
		let dependentServiceOnlyOutput = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
