				public struct DependentService: Instantiable {
				    public init(parallelModuleType: ParallelModuleType) {
				        self.parallelModuleType = parallelModuleType
				    }
				    @Instantiated let parallelModuleType: ParallelModuleType
				}
				""",
				// ParallelModuleType is NOT @Instantiable in this parse — simulates
				// the conformance being in a parallel module.
			],
