	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_uncoveredDependencyNotSuppressedByGrandchildWithSameLabel() async throws {
		// Child has @Instantiated service: ExternalService (NOT in scope map —
		// @Instantiable is in a parallel module). Grandchild has a tree child
		// also named "service" but of type LocalService. The grandchild's
		// "service" label must NOT suppress the child's uncovered dep.
		// Non-root module to skip production validation.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public struct ExternalService {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(child: Child) { self.child = child }
				    @Instantiated let child: Child
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Child: Instantiable {
				    public init(grandchild: Grandchild, service: ExternalService) {
				        self.grandchild = grandchild
				        self.service = service
				    }
				    @Instantiated let grandchild: Grandchild
				    @Instantiated let service: ExternalService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Grandchild: Instantiable {
				    public init(service: LocalService) { self.service = service }
				    @Instantiated let service: LocalService
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct LocalService: Instantiable {
				    public init() {}
				}
				""",
				// ExternalService is NOT @Instantiable(generateMock: true) here — simulates parallel module.
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// ExternalService appears as required parameter despite grandchild having
		// a different "service" (LocalService) in the tree. Both disambiguated.
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            child: Child.SafeDIMockConfiguration = .init()
		        ) {
		            self.child = child
		        }

		        let child: Child.SafeDIMockConfiguration
		    }

		    static func mock(
		        service: ExternalService,
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_child() -> Child {
		            func __safeDI_grandchild() -> Grandchild {
		                let service = if let safeDIBuilder = safeDIOverrides.child.grandchild.service { safeDIBuilder() } else { LocalService() }
		                return if let safeDIBuilder = safeDIOverrides.child.grandchild.safeDIBuilder { safeDIBuilder(service) } else { Grandchild(service: service) }
		            }
		            let grandchild: Grandchild = __safeDI_grandchild()
		            return if let safeDIBuilder = safeDIOverrides.child.safeDIBuilder { safeDIBuilder(grandchild, service) } else { Child(grandchild: grandchild, service: service) }
		        }
		        let child: Child = __safeDI_child()
		        return Root(child: child)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

