				        self.childBBuilder = childBBuilder
				    }
				    @Instantiated let childABuilder: Instantiator<ChildA>
				    @Instantiated let childBBuilder: Instantiator<ChildB>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildA: Instantiable {
				    public init(shared: Shared, name: String) {
				        self.shared = shared
				        self.name = name
				    }
				    @Instantiated let shared: Shared
				    @Forwarded let name: String
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ChildB: Instantiable {
				    public init(shared: Shared, name: String) {
				        self.shared = shared
				        self.name = name
				    }
				    @Received let shared: Shared
				    @Forwarded let name: String
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Shared: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            childABuilder: ChildA.SafeDIMockConfiguration = .init(),
		            shared: (() -> Shared)? = nil,
		            childBBuilder: ((Shared, String) -> ChildB)? = nil
		        ) {
		            self.childABuilder = childABuilder
		            self.shared = shared
		            self.childBBuilder = childBBuilder
		        }

		        let childABuilder: ChildA.SafeDIMockConfiguration
		        let shared: (() -> Shared)?
		        let childBBuilder: ((Shared, String) -> ChildB)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_childABuilder(name: String) -> ChildA {
		            let shared = if let safeDIBuilder = safeDIOverrides.childABuilder.shared { safeDIBuilder() } else { Shared() }
		            return if let safeDIBuilder = safeDIOverrides.childABuilder.safeDIBuilder { safeDIBuilder(shared, name) } else { ChildA(shared: shared, name: name) }
		        }
		        let childABuilder = Instantiator<ChildA> {
