	@Test
	mutating func mock_generatedForFullyLazySendableInstantiatorCycle() async throws {
		// A → B → C → A, all SendableInstantiator (fully lazy cycle of size 3).
		// Back-edge selected by alphabetical SCC: (C, A) — A's slot is pruned
		// from C's SafeDIMockConfiguration. Every override read inside the
		// nested @Sendable functions is extracted before the outermost one.
		// No `safeDIOverrides.aBuilder.bBuilder.cBuilder.aBuilder.safeDIBuilder`
		// extraction may be emitted — that field was removed from C's config struct, so the
		// path doesn't compile. The cycle leaf falls back to the outer A
		// wrapper via the standard cycle binding.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(aBuilder: SendableInstantiator<A>) {
				        self.aBuilder = aBuilder
				    }
				    @Instantiated let aBuilder: SendableInstantiator<A>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct A: Instantiable {
				    public init(bBuilder: SendableInstantiator<B>) {
				        self.bBuilder = bBuilder
				    }
				    @Instantiated let bBuilder: SendableInstantiator<B>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct B: Instantiable {
				    public init(cBuilder: SendableInstantiator<C>) {
				        self.cBuilder = cBuilder
				    }
				    @Instantiated let cBuilder: SendableInstantiator<C>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct C: Instantiable {
				    public init(aBuilder: SendableInstantiator<A>) {
				        self.aBuilder = aBuilder
				    }
				    @Instantiated let aBuilder: SendableInstantiator<A>
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 4)
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            aBuilder: A.SafeDIMockConfiguration = .init()
		        ) {
		            self.aBuilder = aBuilder
		        }

		        let aBuilder: A.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder = safeDIOverrides.aBuilder.bBuilder.safeDIBuilder
		        let __safeDI_aBuilder__aBuilder_bBuilder_cBuilder_safeDIBuilder = safeDIOverrides.aBuilder.bBuilder.cBuilder.safeDIBuilder
		        let __safeDI_aBuilder__safeDIBuilder = safeDIOverrides.aBuilder.safeDIBuilder
		        @Sendable func __safeDI_aBuilder() -> A {
		            @Sendable func __safeDI_bBuilder() -> B {
		                @Sendable func __safeDI_cBuilder() -> C {
		                    let aBuilder = SendableInstantiator<A>(__safeDI_aBuilder)
		                    return if let safeDIBuilder = __safeDI_aBuilder__aBuilder_bBuilder_cBuilder_safeDIBuilder { safeDIBuilder(aBuilder) } else { C(aBuilder: aBuilder) }
		                }
		                let cBuilder = SendableInstantiator<C>(__safeDI_cBuilder)
		                return if let safeDIBuilder = __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder { safeDIBuilder(cBuilder) } else { B(cBuilder: cBuilder) }
		            }
		            let bBuilder = SendableInstantiator<B>(__safeDI_bBuilder)
		            return if let safeDIBuilder = __safeDI_aBuilder__safeDIBuilder { safeDIBuilder(bBuilder) } else { A(bBuilder: bBuilder) }
		        }
		        let aBuilder = SendableInstantiator<A>(__safeDI_aBuilder)
		        return Root(aBuilder: aBuilder)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		// C's configuration struct must NOT expose an `aBuilder` field — the
		// (C, A) back-edge was pruned by the global feedback arc set. If the
		// slot were present, Root's mock body would emit a
		// `safeDIOverrides.aBuilder.bBuilder.cBuilder.aBuilder.safeDIBuilder`
		// extraction and the generated code wouldn't compile.
		#expect(output.mockFiles["C+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension C {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            aBuilder: A.SafeDIMockConfiguration = .init()
		        ) {
		            self.aBuilder = aBuilder
		        }

		        let aBuilder: A.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> C {
		        let __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder = safeDIOverrides.aBuilder.bBuilder.safeDIBuilder
		        let __safeDI_aBuilder__aBuilder_bBuilder_cBuilder_safeDIBuilder = safeDIOverrides.aBuilder.bBuilder.cBuilder.safeDIBuilder
		        let __safeDI_aBuilder__safeDIBuilder = safeDIOverrides.aBuilder.safeDIBuilder
		        @Sendable func __safeDI_aBuilder() -> A {
		            @Sendable func __safeDI_bBuilder() -> B {
		                @Sendable func __safeDI_cBuilder() -> C {
		                    let aBuilder = SendableInstantiator<A>(__safeDI_aBuilder)
		                    return if let safeDIBuilder = __safeDI_aBuilder__aBuilder_bBuilder_cBuilder_safeDIBuilder { safeDIBuilder(aBuilder) } else { C(aBuilder: aBuilder) }
		                }
		                let cBuilder = SendableInstantiator<C>(__safeDI_cBuilder)
		                return if let safeDIBuilder = __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder { safeDIBuilder(cBuilder) } else { B(cBuilder: cBuilder) }
		            }
		            let bBuilder = SendableInstantiator<B>(__safeDI_bBuilder)
		            return if let safeDIBuilder = __safeDI_aBuilder__safeDIBuilder { safeDIBuilder(bBuilder) } else { A(bBuilder: bBuilder) }
		        }
		        let aBuilder = SendableInstantiator<A>(__safeDI_aBuilder)
		        return C(aBuilder: aBuilder)
		    }
		}
		#endif

		#if DEBUG
		extension C {
		    /// Configuration for how this type is constructed within a mock tree.
		    struct SafeDIMockConfiguration {
		        init(
		            _ safeDIBuilder: (@Sendable (SendableInstantiator<A>) -> C)? = nil
		        ) {
		            self.safeDIBuilder = safeDIBuilder
		        }

		        /// Overrides how this type is constructed. Parameters match the type’s initializer or custom mock method. When `nil`, the default generated construction function is used.
		        let safeDIBuilder: (@Sendable (SendableInstantiator<A>) -> C)?
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["C+SafeDIMock.swift"] ?? "")")
	}

