	// The time limit only turns a hang into a failure, so it sits far above any scheduling delay:
	// this test does a fraction of a second of work, but on a loaded CI runner it can wait more
	// than a minute behind the rest of the suite.
	@Test(.timeLimit(.minutes(10)))
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatesWithinTimeLimit_whenReceivedDependenciesFormDeepChainOfDiamonds() async throws {
		// Each service receives the two services before it and the service at half its index.
		// The number of distinct received-dependency paths from the last service grows
		// exponentially with the service count, while the number of services does not.
		// Walking every path took about 1.66 times longer per added service (23 seconds at 30
		// services), so at this count it would take tens of thousands of years on any hardware.
		let serviceCount = 80
		let serviceFiles = (0..<serviceCount).map { index in
			let receivedIndices = Set([index - 1, index - 2, index / 2])
				.filter { $0 >= 0 && $0 < index }
				.sorted()
			let initializerParameters = receivedIndices.map { "service\($0): Service\($0)" }.joined(separator: ", ")
			let receivedProperties = receivedIndices.map { "    @Received let service\($0): Service\($0)" }.joined(separator: "\n")
			return """
			@Instantiable
			public struct Service\(index): Instantiable {
			    public init(\(initializerParameters)) {
			        fatalError("SafeDI doesn't inspect the initializer body")
			    }

			\(receivedProperties)
			}
			"""
		}
		let featureInitializerParameters = (0..<serviceCount).map { "service\($0): Service\($0)" }.joined(separator: ", ")
		let featureProperties = (0..<serviceCount).map { "    @Instantiated let service\($0): Service\($0)" }.joined(separator: "\n")
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(\(featureInitializerParameters)) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				\(featureProperties)
				}
				""",
			] + serviceFiles,
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			skipCompileVerification: true,
		)

		#expect(output.mockFiles.keys.sorted() == ["Feature+SafeDIMock.swift"])
		#expect(output.dependencyTreeFiles.isEmpty)
	}

	// See `mock_generatesWithinTimeLimit_whenReceivedDependenciesFormDeepChainOfDiamonds` for the limit.
	@Test(.timeLimit(.minutes(10)))
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatesWithinTimeLimit_whenPromotedReceivedDependenciesFormDeepChainOfDiamonds() async throws {
		// As above, but Feature receives only the last service, so every service is
		// promoted to the mock root and the mock root's cycle validation walks the
		// exponential number of received-dependency paths between promoted siblings.
		let serviceCount = 80
		let serviceFiles = (0..<serviceCount).map { index in
			let receivedIndices = Set([index - 1, index - 2, index / 2])
				.filter { $0 >= 0 && $0 < index }
				.sorted()
			let initializerParameters = receivedIndices.map { "service\($0): Service\($0)" }.joined(separator: ", ")
			let receivedProperties = receivedIndices.map { "    @Received let service\($0): Service\($0)" }.joined(separator: "\n")
			return """
			@Instantiable
			public struct Service\(index): Instantiable {
			    public init(\(initializerParameters)) {
			        fatalError("SafeDI doesn't inspect the initializer body")
			    }

			\(receivedProperties)
			}
			"""
		}
		let lastService = serviceCount - 1
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(service\(lastService): Service\(lastService)) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Received let service\(lastService): Service\(lastService)
				}
				""",
			] + serviceFiles,
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			skipCompileVerification: true,
		)

		#expect(output.mockFiles.keys.sorted() == ["Feature+SafeDIMock.swift"])
		#expect(output.dependencyTreeFiles.isEmpty)
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_promotesDependencyReceivedInsideLazyCycle_whenAnotherSubtreeEnteredTheCycleFirst() async throws {
		// `Y`'s subtree enters the `A` <-> `B` cycle at `B` and declares the `z` that `B`
		// receives, so `Y` needs nothing from the root. `X`'s subtree enters the same cycle
		// at `A` and declares no `z`, so the root must provide one. Walking `Y` first left
		// `A`'s received dependencies recorded without `B`'s, and `X` then appeared to need
		// no `z`: the mock required a `z` parameter instead of building one. When both `x`
		// and `y` are received, which subtree is walked first follows set iteration order.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(x: X, y: Y) {
				        self.x = x
				        self.y = y
				    }
				    @Received let x: X
				    @Instantiated let y: Y
				}
				""",
				"""
				@Instantiable
				public struct X: Instantiable {
				    public init(a: Instantiator<A>) {
				        self.a = a
				    }
				    @Instantiated let a: Instantiator<A>
				}
				""",
				"""
				@Instantiable
				public struct Y: Instantiable {
				    public init(b: Instantiator<B>, z: Z) {
				        self.b = b
				        self.z = z
				    }
				    @Instantiated let b: Instantiator<B>
				    @Instantiated let z: Z
				}
				""",
				"""
				@Instantiable
				public struct A: Instantiable {
				    public init(b: Instantiator<B>) {
				        self.b = b
				    }
				    @Instantiated let b: Instantiator<B>
				}
				""",
				"""
				@Instantiable
				public struct B: Instantiable {
				    public init(a: Instantiator<A>, z: Z) {
				        self.a = a
				        self.z = z
				    }
				    @Instantiated let a: Instantiator<A>
				    @Received let z: Z
				}
				""",
				"""
				@Instantiable
				public struct Z: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.keys.sorted() == ["Root+SafeDIMock.swift"])
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            y: Y.SafeDIMockConfiguration = .init(),
		            z: (() -> Z)? = nil,
		            x: X.SafeDIMockConfiguration = .init()
		        ) {
		            self.y = y
		            self.z = z
		            self.x = x
		        }

		        let y: Y.SafeDIMockConfiguration
		        let z: (() -> Z)?
		        let x: X.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_y() -> Y {
		            let z = if let safeDIBuilder = safeDIOverrides.y.z { safeDIBuilder() } else { Z() }
		            func __safeDI_b() -> B {
		                func __safeDI_a() -> A {
		                    let b = Instantiator<B>(__safeDI_b)
		                    return A(b: b)
		                }
		                let a = Instantiator<A>(__safeDI_a)
		                return if let safeDIBuilder = safeDIOverrides.y.b.safeDIBuilder { safeDIBuilder(a, z) } else { B(a: a, z: z) }
		            }
		            let b = Instantiator<B>(__safeDI_b)
		            return if let safeDIBuilder = safeDIOverrides.y.safeDIBuilder { safeDIBuilder(b, z) } else { Y(b: b, z: z) }
		        }
		        let y: Y = __safeDI_y()
		        let z = if let safeDIBuilder = safeDIOverrides.z { safeDIBuilder() } else { Z() }
		        func __safeDI_x() -> X {
		            func __safeDI_a() -> A {
		                func __safeDI_b() -> B {
		                    let a = Instantiator<A>(__safeDI_a)
		                    return if let safeDIBuilder = safeDIOverrides.x.a.b.safeDIBuilder { safeDIBuilder(a, z) } else { B(a: a, z: z) }
		                }
		                let b = Instantiator<B>(__safeDI_b)
		                return if let safeDIBuilder = safeDIOverrides.x.a.safeDIBuilder { safeDIBuilder(b) } else { A(b: b) }
		            }
		            let a = Instantiator<A>(__safeDI_a)
		            return if let safeDIBuilder = safeDIOverrides.x.safeDIBuilder { safeDIBuilder(a) } else { X(a: a) }
		        }
		        let x: X = __safeDI_x()
		        return Root(x: x, y: y)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_promotesDependencyReceivedInsideLazyCycle_whenTypeInCycleIsReachedTwice() async throws {
		// `A` reaches `C` directly and through `B`, and `C` closes the cycle back to `A`, so
		// what `C` receives is collected while `A`'s walk is unfinished and reused for `A`'s
		// second path to it.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(x: X) {
				        self.x = x
				    }
				    @Received let x: X
				}
				""",
				"""
				@Instantiable
				public struct X: Instantiable {
				    public init(a: Instantiator<A>) {
				        self.a = a
				    }
				    @Instantiated let a: Instantiator<A>
				}
				""",
				"""
				@Instantiable
				public struct A: Instantiable {
				    public init(b: Instantiator<B>, c: Instantiator<C>) {
				        self.b = b
				        self.c = c
				    }
				    @Instantiated let b: Instantiator<B>
				    @Instantiated let c: Instantiator<C>
				}
				""",
				"""
				@Instantiable
				public struct B: Instantiable {
				    public init(c: Instantiator<C>) {
				        self.c = c
				    }
				    @Instantiated let c: Instantiator<C>
				}
				""",
				"""
				@Instantiable
				public struct C: Instantiable {
				    public init(a: Instantiator<A>, z: Z) {
				        self.a = a
				        self.z = z
				    }
				    @Instantiated let a: Instantiator<A>
				    @Received let z: Z
				}
				""",
				"""
				@Instantiable
				public struct Z: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.keys.sorted() == ["Root+SafeDIMock.swift"])
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            z: (() -> Z)? = nil,
		            x: X.SafeDIMockConfiguration = .init()
		        ) {
		            self.z = z
		            self.x = x
		        }

		        let z: (() -> Z)?
		        let x: X.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let z = if let safeDIBuilder = safeDIOverrides.z { safeDIBuilder() } else { Z() }
		        func __safeDI_x() -> X {
		            func __safeDI_a() -> A {
		                func __safeDI_b() -> B {
		                    func __safeDI_c() -> C {
		                        let a = Instantiator<A>(__safeDI_a)
		                        return if let safeDIBuilder = safeDIOverrides.x.a.b.c.safeDIBuilder { safeDIBuilder(a, z) } else { C(a: a, z: z) }
		                    }
		                    let c = Instantiator<C>(__safeDI_c)
		                    return if let safeDIBuilder = safeDIOverrides.x.a.b.safeDIBuilder { safeDIBuilder(c) } else { B(c: c) }
		                }
		                let b = Instantiator<B>(__safeDI_b)
		                func __safeDI_c() -> C {
		                    let a = Instantiator<A>(__safeDI_a)
		                    return if let safeDIBuilder = safeDIOverrides.x.a.c.safeDIBuilder { safeDIBuilder(a, z) } else { C(a: a, z: z) }
		                }
		                let c = Instantiator<C>(__safeDI_c)
		                return if let safeDIBuilder = safeDIOverrides.x.a.safeDIBuilder { safeDIBuilder(b, c) } else { A(b: b, c: c) }
		            }
		            let a = Instantiator<A>(__safeDI_a)
		            return if let safeDIBuilder = safeDIOverrides.x.safeDIBuilder { safeDIBuilder(a) } else { X(a: a) }
		        }
		        let x: X = __safeDI_x()
		        return Root(x: x)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

