	@Test
	mutating func mock_generatedForLazyCycleBeneathConstantChild() async throws {
		// Root → A (constant, not Instantiator) → Instantiator<B> → B → Instantiator<A>.
		// Fully-lazy 2-node cycle A↔B, but A is a constant child of Root, so
		// A's mock code takes the constant-wrapper recursion path in
		// `generateMockBodyBindings` (as opposed to the Instantiator path used
		// by the other cycle tests). This test pins that the constant-wrapper
		// recursion threads cycle context to its descendants: without it, a
		// back-edge pruned from B's `SafeDIMockConfiguration` could surface as
		// a dangling `safeDIOverrides.a.bBuilder.aBuilder.safeDIBuilder`
		// reference that does not typecheck.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(a: A) {
				        self.a = a
				    }
				    @Instantiated let a: A
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct A: Instantiable {
				    public init(bBuilder: Instantiator<B>) {
				        self.bBuilder = bBuilder
				    }
				    @Instantiated let bBuilder: Instantiator<B>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct B: Instantiable {
				    public init(aBuilder: Instantiator<A>) {
				        self.aBuilder = aBuilder
				    }
				    @Instantiated let aBuilder: Instantiator<A>
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            a: A.SafeDIMockConfiguration = .init()
		        ) {
		            self.a = a
		        }

		        let a: A.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_a() -> A {
		            func __safeDI_bBuilder() -> B {
		                func __safeDI_aBuilder() -> A {
		                    let bBuilder = Instantiator<B>(__safeDI_bBuilder)
		                    return A(bBuilder: bBuilder)
		                }
		                let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		                return if let safeDIBuilder = safeDIOverrides.a.bBuilder.safeDIBuilder { safeDIBuilder(aBuilder) } else { B(aBuilder: aBuilder) }
		            }
		            let bBuilder = Instantiator<B>(__safeDI_bBuilder)
		            return if let safeDIBuilder = safeDIOverrides.a.safeDIBuilder { safeDIBuilder(bBuilder) } else { A(bBuilder: bBuilder) }
		        }
		        let a: A = __safeDI_a()
		        return Root(a: a)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatedForErasedInstantiatorBackEdgeInLazyCycle() async throws {
		// Z → ErasedInstantiator<(), AnyEraser> → ConcreteView → Instantiator<Z>.
		// All hops are lazy (ErasedInstantiator + Instantiator are non-constant),
		// so `throwIfInvalidCycle` accepts the cycle. Alphabetical DFS starts at
		// ConcreteView, so the selected back-edge is (Z, ConcreteView) — the
		// erased edge. Z's viewBuilder child therefore has
		// `erasedToConcreteExistential == true` AND `thisOverrideReachable == false`
		// when Z's mock body is generated, exercising the branches removed in
		// commit 5b8b9a4.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public final class AnyEraser {
				    public init<T>(_ wrapped: T) {}
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(zBuilder: Instantiator<Z>) {
				        self.zBuilder = zBuilder
				    }
				    @Instantiated let zBuilder: Instantiator<Z>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Z: Instantiable {
				    public init(viewBuilder: ErasedInstantiator<(), AnyEraser>) {
				        self.viewBuilder = viewBuilder
				    }
				    @Instantiated(fulfilledByType: "ConcreteView", erasedToConcreteExistential: true) let viewBuilder: ErasedInstantiator<(), AnyEraser>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct ConcreteView: Instantiable {
				    public init(zBuilder: Instantiator<Z>) {
				        self.zBuilder = zBuilder
				    }
				    @Instantiated let zBuilder: Instantiator<Z>
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            zBuilder: Z.SafeDIMockConfiguration = .init()
		        ) {
		            self.zBuilder = zBuilder
		        }

		        let zBuilder: Z.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_zBuilder() -> Z {
		            func __safeDI_viewBuilder() -> AnyEraser {
		                let zBuilder = Instantiator<Z>(__safeDI_zBuilder)
		                return AnyEraser(ConcreteView(zBuilder: zBuilder))
		            }
		            let viewBuilder = ErasedInstantiator<(), AnyEraser>(__safeDI_viewBuilder)
		            return if let safeDIBuilder = safeDIOverrides.zBuilder.safeDIBuilder { safeDIBuilder(viewBuilder) } else { Z(viewBuilder: viewBuilder) }
		        }
		        let zBuilder = Instantiator<Z>(__safeDI_zBuilder)
		        return Root(zBuilder: zBuilder)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
	}

