	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_passesNilToOnlyIfAvailableReceiver_whenReceiverIsBuiltInsideAncestorThatSiblingRequires() async throws {
		// `D`, built inside `c`, receives `c` and `e` only if available. `c` is still being constructed, so both mocks
		// hand `D` `nil` for it, as the production initializer does. `Root.mock()` builds `e`, which requires `c`, after
		// `c`, so `D` gets `nil` for `e` too; `E.mock()` hands `D` its optional `e` override.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public final class Root: Instantiable {
				    public init(c: C, e: E) {
				        self.c = c
				        self.e = e
				    }

				    @Instantiated let c: C
				    @Instantiated let e: E
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class C: Instantiable {
				    public init(d: D) {
				        self.d = d
				    }

				    @Instantiated let d: D
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class D: Instantiable {
				    public init(c: C?, e: E?) {
				        self.c = c
				        self.e = e
				    }

				    @Received(onlyIfAvailable: true) let c: C?
				    @Received(onlyIfAvailable: true) let e: E?
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public final class E: Instantiable {
				    public init(c: C) {
				        self.c = c
				    }

				    @Received let c: C
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            c: C.SafeDIMockConfiguration = .init(),
		            e: ((C) -> E)? = nil
		        ) {
		            self.c = c
		            self.e = e
		        }

		        let c: C.SafeDIMockConfiguration
		        let e: ((C) -> E)?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        func __safeDI_c() -> C {
		            let d = if let safeDIBuilder = safeDIOverrides.c.d { safeDIBuilder(nil, nil) } else { D(c: nil, e: nil) }
		            return if let safeDIBuilder = safeDIOverrides.c.safeDIBuilder { safeDIBuilder(d) } else { C(d: d) }
		        }
		        let c: C = __safeDI_c()
		        let e = if let safeDIBuilder = safeDIOverrides.e { safeDIBuilder(c) } else { E(c: c) }
		        return Root(c: c, e: e)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")
		#expect(output.mockFiles["E+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension E {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            c: C.SafeDIMockConfiguration = .init(),
		            e: E? = nil
		        ) {
		            self.c = c
		            self.e = e
		        }

		        let c: C.SafeDIMockConfiguration
		        let e: E?
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> E {
		        let e: E? = safeDIOverrides.e
		        func __safeDI_c() -> C {
		            let d = if let safeDIBuilder = safeDIOverrides.c.d { safeDIBuilder(nil, e) } else { D(c: nil, e: e) }
		            return if let safeDIBuilder = safeDIOverrides.c.safeDIBuilder { safeDIBuilder(d) } else { C(d: d) }
		        }
		        let c: C = __safeDI_c()
		        return E(c: c)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["E+SafeDIMock.swift"] ?? "")")
	}

