		        let aBuilder: A.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder = safeDIOverrides.aBuilder.bBuilder.safeDIBuilder
		        let __safeDI_aBuilder__safeDIBuilder = safeDIOverrides.aBuilder.safeDIBuilder
		        @Sendable func __safeDI_aBuilder() -> A {
		            @Sendable func __safeDI_bBuilder() -> B {
		                let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		                return if let safeDIBuilder = __safeDI_aBuilder__aBuilder_bBuilder_safeDIBuilder { safeDIBuilder(aBuilder) } else { B(aBuilder: aBuilder) }
		            }
		            let bBuilder = SendableInstantiator<B>(__safeDI_bBuilder)
		            return if let safeDIBuilder = __safeDI_aBuilder__safeDIBuilder { safeDIBuilder(bBuilder) } else { A(bBuilder: bBuilder) }
		        }
		        let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		        return Root(aBuilder: aBuilder)
		    }
		}
		#endif
		""")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_passesNilForOnlyIfAvailableAlias_whenAliasIsFulfilledByNonOptionalFormOfPromotedOptionalInstantiatorBeingBuilt() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public final class Screen: Instantiable {
				    public init(aBuilder: Instantiator<A>?) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Received let aBuilder: Instantiator<A>?
				}
				""",
				"""
				@Instantiable
				public final class A: Instantiable {
				    public init(b: B) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let b: B
				}
				""",
				"""
				@Instantiable
				public final class B: Instantiable {
				    public init(aBuilderAlias: Instantiator<A>?) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Received(fulfilledByDependencyNamed: "aBuilder", ofType: Instantiator<A>.self, onlyIfAvailable: true) let aBuilderAlias: Instantiator<A>?
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Screen+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Screen {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            aBuilder: A.SafeDIMockConfiguration = .init()
		        ) {
		            self.aBuilder = aBuilder
		        }

		        let aBuilder: A.SafeDIMockConfiguration
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Screen {
		        func __safeDI_aBuilder() -> A {
		            let b = if let safeDIBuilder = safeDIOverrides.aBuilder.b { safeDIBuilder(nil) } else { B(aBuilderAlias: nil) }
		            return if let safeDIBuilder = safeDIOverrides.aBuilder.safeDIBuilder { safeDIBuilder(b) } else { A(b: b) }
		        }
		        let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		        return Screen(aBuilder: aBuilder)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Screen+SafeDIMock.swift"] ?? "")")
	}

	@Test
	mutating func mock_takesOneParameterForDependencyMockCannotBuild_whenTwoTypesInTreeInstantiateIt() async throws {
		// `Engine` is not `@Instantiable`, so the mock cannot build it: it is a flat `mock()` parameter. Two types
		// in the tree instantiate `engine: Engine`, and the mock takes it once and passes it to both.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public struct Engine {
				    public init() {}
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(childA: ChildA, childB: ChildB) {
				        self.childA = childA
				        self.childB = childB
				    }
				    @Instantiated let childA: ChildA
				    @Instantiated let childB: ChildB
				}
				""",
				"""
				@Instantiable
				public struct ChildA: Instantiable {
				    public init(engine: Engine) { self.engine = engine }
				    @Instantiated let engine: Engine
				}
				""",
				"""
				@Instantiable
				public struct ChildB: Instantiable {
				    public init(engine: Engine) { self.engine = engine }
				    @Instantiated let engine: Engine
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            childA: ((Engine) -> ChildA)? = nil,
		            childB: ((Engine) -> ChildB)? = nil
		        ) {
		            self.childA = childA
		            self.childB = childB
		        }

		        let childA: ((Engine) -> ChildA)?
		        let childB: ((Engine) -> ChildB)?
		    }

		    static func mock(
		        engine: Engine,
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let childA = if let safeDIBuilder = safeDIOverrides.childA { safeDIBuilder(engine) } else { ChildA(engine: engine) }
		        let childB = if let safeDIBuilder = safeDIOverrides.childB { safeDIBuilder(engine) } else { ChildB(engine: engine) }
		        return Root(childA: childA, childB: childB)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Root+SafeDIMock.swift"] ?? "")")

		#expect(output.mockConfigurationFile == emptyMockConfigurationFileOutput, "Unexpected output \(output.mockConfigurationFile ?? "")")
	}

	// MARK: Private

	private var filesToDelete: [URL]
}
